import {isSVCOResearchOnly,svcoResearchOnlyHTML} from './svco-research-only.js';
import {catalogProsePairs} from './locales/company-catalog.js';
import {registerCatalog,t,localizedText} from './i18n.js';
import {MISSING_RESEARCH_STAGES,searchCompanies} from './company-catalog.js';
registerCatalog('directory',{en:{
 researchOnly:'Research complete · valuation blocked',broker:'Robinhood public support',brokerScope:'Public buy/sell support checked {date}. Account-specific eligibility and current trading availability are not verified.',currencyUnknown:'Quote currency not yet verified',search:'Find a company',company:'Company',ready:'Reviewed annual case',pending:'Research pending',empty:'No matching US-listed company with verified public Robinhood support.',unavailable:'The expanded directory could not be loaded. The original 14 reviewed companies remain available.',scope:'Company directory',coverage:'Coverage and unresolved identities',coverageNote:'These Atlas entities are not selectable securities. They are private, unlisted, or still require identity, listing or ownership clarification; a proposed ticker does not establish a tradable security.',identity:'Verified listing identity',checked:'Identity checked {date}',security:'{exchange} · {ticker} · {type} · {currency}',notice:'Listing identity is verified. A reviewed valuation package is not yet available. No price, estimated value, default assumptions or simulation is supplied.',next:'Research required before valuation',financials:'Financial anchor: source-dated statements, fiscal period, accounting basis and reporting currency.',history:'Historical evidence: comparable annual history, normalization and source ledger.',operating:'Operating case: company-specific growth, margins, tax, reinvestment and discount-rate rationale.',capital:'Capital claims: debt, cash, dilution, security class, ADR ratio and currency reconciliation.',valuation:'Model review: terminal economics, timing, claims gates and independently checked uncertainty settings.',sources:'Primary identity evidence',atlas:'Original Atlas context',results:'{count} matching companies',mapping:'Mapping notes',disclosure:'Coverage note'
},'zh-Hans':{
 researchOnly:'研究已完成 · 估值未开放',broker:'Robinhood 公开支持',brokerScope:'已于 {date} 核实公开买卖支持；尚未验证个人账户资格及当前交易可用性。',currencyUnknown:'报价币别尚未核实',search:'搜寻公司',company:'公司',ready:'已审核年度案例',pending:'研究待完成',empty:'没有符合的美国上市公司，或尚未核实 Robinhood 公开支持。',unavailable:'扩充公司目录载入失败。原有 14 家已审核公司仍可使用。',scope:'公司目录',coverage:'涵盖范围与待厘清身分',coverageNote:'这些 Atlas 实体并非可选取的证券。其中包括私营、未上市或公司身份、上市及所有权证据仍待厘清的实体；拟用代号不代表已可交易。',identity:'已核实上市身分',checked:'身分核实日期：{date}',security:'{exchange} · {ticker} · {type} · {currency}',notice:'上市身分已核实，但尚无已审核的估值资料包。此处不提供股价、估算价值、预设假设或模拟。',next:'估值前尚需完成的研究',financials:'财务起点：具来源日期的报表、会计期间、会计基础与报告币别。',history:'历史证据：可比较的年度历史、常态化调整与来源清单。',operating:'营运案例：公司专属的成长、利润率、税率、再投资与折现率依据。',capital:'资本请求权：负债、现金、稀释、证券类别、ADR 比率与币别调节。',valuation:'模型审核：终值经济性、时间基准、请求权门槛及独立检查的不确定性设定。',sources:'主要身分证据',atlas:'原始 Atlas 脉络',results:'符合条件的公司：{count} 家',mapping:'对应说明',disclosure:'涵盖说明'
}});
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const label=key=>localizedText('directory.'+key);
const proseKeys=new Map(catalogProsePairs.map(([source],index)=>[source,String(index)]));
registerCatalog('catalog-prose',{en:Object.fromEntries(catalogProsePairs.map(([source],index)=>[index,source])),'zh-Hans':Object.fromEntries(catalogProsePairs.map(([,translation],index)=>[index,translation]))});
export const catalogProseHTML=value=>proseKeys.has(value)?localizedText('catalog-prose.'+proseKeys.get(value)):esc(value);

export function companyOptionsHTML(entries,selected){return entries.map(row=>`<option value="${esc(row.id)}" ${row.id===selected?'selected':''}>${esc(row.ticker)} · ${esc(row.company)} · ${esc(t('directory.'+(row.readiness==='ready'?'ready':isSVCOResearchOnly(row)?'researchOnly':'pending')))}</option>`).join('');}
export function companyPickerControlsHTML(entries,selected){return `<label for="catalog-search">${label('search')}</label><input id="catalog-search" type="search" autocomplete="off" aria-controls="research-company" aria-describedby="catalog-search-status"><label for="research-company">${label('company')}</label><select id="research-company">${companyOptionsHTML(entries,selected)}</select><span id="catalog-search-status" class="micro" role="status"></span>`;}
export function companyPickerHTML(entries,selected){return `<div class="catalog-picker">${companyPickerControlsHTML(entries,selected)}</div>`;}
export function coverageHTML(catalog,error){return `${error?`<p class="research-warning">${label('unavailable')}</p>`:''}${catalog?.coverage.length?`<details class="catalog-coverage"><summary>${label('coverage')} (${catalog.coverage.length})</summary><p>${label('coverageNote')}</p><ul>${catalog.coverage.map(row=>`<li><b>${catalogProseHTML(row.company)}</b> · ${catalogProseHTML(row.reason)}${row.sourceURLs?.length?` <a href="${esc(row.sourceURLs[0])}" target="_blank" rel="noopener">${label('sources')} ↗</a>`:''}</li>`).join('')}</ul></details>`:''}`;}
export function pendingCompanyHTML(row){return `<article class="catalog-pending" data-company-readiness="research-pending"><span class="eyebrow">${label(isSVCOResearchOnly(row)?'researchOnly':'pending')}</span><h2>${esc(row.company)}</h2>${isSVCOResearchOnly(row)?svcoResearchOnlyHTML():`<p>${label('notice')}</p>`}<h3>${label('identity')}</h3><p>${esc(row.ticker)} · ${catalogProseHTML(row.exchange)} · ${esc(row.nativeTicker)} · ${catalogProseHTML(row.securityType)} · ${row.currency?esc(row.currency):label('currencyUnknown')}</p><p>${localizedText('directory.checked',{date:row.checkedAt})}</p><p>${catalogProseHTML(row.evidence)}</p>${row.note?`<p>${label('mapping')}: ${catalogProseHTML(row.note)}</p>`:''}${row.robinhood?`<p><a href="${esc(row.robinhood.url)}" target="_blank" rel="noopener">${label('broker')} ↗</a> · ${localizedText('directory.brokerScope',{date:row.robinhood.checkedAt})}</p>`:''}<h3>${label('sources')}</h3><ul>${row.sourceURLs.map((url,index)=>`<li><a href="${esc(url)}" target="_blank" rel="noopener">${label('sources')} ${index+1} ↗</a></li>`).join('')}</ul>${isSVCOResearchOnly(row)?'':`<h3>${label('next')}</h3><ol>${MISSING_RESEARCH_STAGES.map(stage=>`<li>${label(stage)}</li>`).join('')}</ol>`}</article>`;}
export function bindCompanyPicker(root,entries,selected,choose){
 const input=root.querySelector('#catalog-search'),select=root.querySelector('#research-company'),status=root.querySelector('#catalog-search-status');
 if(!select)return;
 select.onchange=event=>{if(event.target.value)choose(event.target.value);root.querySelector('#research-company')?.focus({preventScroll:true});};
 if(input)input.oninput=()=>{const matches=searchCompanies(entries,input.value);select.innerHTML=companyOptionsHTML(matches,selected);select.value=matches.some(row=>row.id===selected)?selected:'';status.textContent=matches.length?t('directory.results',{count:matches.length}):t('directory.empty');};
}

/** Update translated option captions without replacing controls or search state. */
export function refreshCompanyPicker(root,entries){
 const select=root.querySelector('#research-company');
 for(const option of select?.querySelectorAll('option')||[]){const row=entries.find(entry=>entry.id===option.value);if(row)option.textContent=`${row.ticker} · ${row.company} · ${t('directory.'+(row.readiness==='ready'?'ready':isSVCOResearchOnly(row)?'researchOnly':'pending'))}`;}
 const input=root.querySelector('#catalog-search'),status=root.querySelector('#catalog-search-status');
 if(input?.value&&status){const count=searchCompanies(entries,input.value).length;status.textContent=count?t('directory.results',{count}):t('directory.empty');}
}
